#!/usr/bin/env bash
# Generate indexes, the all-in-one bundle and tool adapters from source files.
# Usage: tools/build.sh [--check]   (--check: fail if generated files are stale, write nothing)
set -euo pipefail
cd "$(dirname "$0")/.."
export LC_ALL=C

RAW="https://raw.githubusercontent.com/Szmelc-INC/CONVENTIONS.md/main"
GEN_NOTE='<!-- GENERATED by tools/build.sh from sources. Do not edit; edit the source and rebuild. -->'
GENERATED=(
  INDEX.md index.json llms.txt CONVENTIONS.md
  adapters/cursor/szmelc-conventions.mdc
  adapters/copilot/szmelc-conventions.instructions.md
  adapters/kiro/szmelc-conventions.md
)

check=0
[[ ${1:-} == --check ]] && check=1
out=.
if ((check)); then
  out=$(mktemp -d)
  trap 'rm -rf "$out"' EXIT
fi

# --- source discovery -------------------------------------------------------

# Markdown files at depth >= 2, skipping hidden dirs and symlinks.
all_md() {
  find . -mindepth 2 -path './.*' -prune -o -type f -name '*.md' -print | sed 's|^\./||' | sort
}

# status <path> → stable | experimental | legacy | skip
status() {
  case $1 in
    _template/* | adapters/* | global/* | skills/* | tools/* | schema/*) echo skip ;;
    experimental/*) echo experimental ;;
    legacy/*) echo legacy ;;
    *) echo stable ;;
  esac
}

files_with() { local f; while IFS= read -r f; do [[ $(status "$f") == "$1" ]] && echo "$f"; done < <(all_md); }
title() { sed -n '1s/^# //p' "$1"; }
trigger() { sed -n '2s/^> Load when: //p' "$1"; }
# fm <file> <key> → top-level frontmatter value
fm() { awk -v k="$2" 'NR==1&&/^---$/{f=1;next} f&&/^---$/{exit} f&&index($0,k": ")==1{print substr($0,length(k)+3)}' "$1"; }
# Body without leading frontmatter.
body() { awk 'NR==1&&/^---$/{f=1;next} f&&/^---$/{f=0;next} !f' "$1"; }
cell() { local s=$1; s=${s//|/\\|}; printf '%s' "$s"; }
json() { local s=$1; s=${s//\\/\\\\}; s=${s//\"/\\\"}; s=${s//$'\t'/\\t}; printf '"%s"' "$s"; }

mapfile -t STABLE < <(files_with stable)
mapfile -t EXPERIMENTAL < <(files_with experimental)
mapfile -t LEGACY < <(files_with legacy)
mapfile -t SKILLS < <(find skills -mindepth 2 -maxdepth 2 -name SKILL.md | sort)

ALWAYS_TRIGGER='Installed as global instructions (CLAUDE.md, AGENTS.md, GEMINI.md, QWEN.md, …); always active'
ENTRY_TRIGGER='Installed as skill `szmelc-conventions`; entry point and format map'

emit() { mkdir -p "$out/$(dirname "$1")"; cat >"$out/$1"; }

# --- INDEX.md ----------------------------------------------------------------
{
  echo '# Index'
  echo "$GEN_NOTE"
  echo 'Read this once per session. Load only files whose trigger matches the task. Paths are relative to the conventions repo.'
  echo
  echo '## Always on'
  echo '| File | Load when |'
  echo '|---|---|'
  echo "| \`global/AGENTS.md\` | $(cell "$ALWAYS_TRIGGER") |"
  echo "| \`SKILL.md\` | $(cell "$ENTRY_TRIGGER") |"
  echo
  echo '## Rules'
  echo '| File | Load when |'
  echo '|---|---|'
  for f in "${STABLE[@]}"; do echo "| \`$f\` | $(cell "$(trigger "$f")") |"; done
  echo
  echo '## Skills'
  echo '| File | Load when |'
  echo '|---|---|'
  for f in "${SKILLS[@]}"; do echo "| \`$f\` | $(cell "$(fm "$f" description)") |"; done
  echo
  echo '## Experimental (opt-in only)'
  if ((${#EXPERIMENTAL[@]})); then
    echo '| File | Load when |'
    echo '|---|---|'
    for f in "${EXPERIMENTAL[@]}"; do echo "| \`$f\` | $(cell "$(trigger "$f")") |"; done
  else
    echo '_None._'
  fi
  echo
  echo '## Legacy (archive; load only when asked)'
  if ((${#LEGACY[@]})); then
    echo '| File | Title |'
    echo '|---|---|'
    for f in "${LEGACY[@]}"; do echo "| \`$f\` | $(cell "$(title "$f")") |"; done
  else
    echo '_None._'
  fi
} | emit INDEX.md

# --- index.json --------------------------------------------------------------
{
  entries=()
  e() { entries+=("    {\"path\": $(json "$1"), \"title\": $(json "$2"), \"load_when\": $(json "$3"), \"status\": $(json "$4"), \"kind\": $(json "$5")}"); }
  e global/AGENTS.md "$(title global/AGENTS.md)" "$ALWAYS_TRIGGER" always global
  e SKILL.md "$(fm SKILL.md name)" "$ENTRY_TRIGGER" always skill
  for f in "${STABLE[@]}"; do e "$f" "$(title "$f")" "$(trigger "$f")" stable rule; done
  for f in "${SKILLS[@]}"; do e "$f" "$(fm "$f" name)" "$(fm "$f" description)" stable skill; done
  for f in "${EXPERIMENTAL[@]}"; do e "$f" "$(title "$f")" "$(trigger "$f")" experimental rule; done
  for f in "${LEGACY[@]}"; do e "$f" "$(title "$f")" "Only when asked about superseded conventions" legacy archive; done
  echo '{'
  echo '  "$schema": "schema/index.schema.json",'
  echo '  "name": "szmelc-conventions",'
  echo '  "repo": "https://github.com/Szmelc-INC/CONVENTIONS.md",'
  echo '  "entries": ['
  last=$((${#entries[@]} - 1))
  for i in "${!entries[@]}"; do
    if ((i < last)); then echo "${entries[$i]},"; else echo "${entries[$i]}"; fi
  done
  echo '  ]'
  echo '}'
} | emit index.json

# --- llms.txt ----------------------------------------------------------------
{
  echo '# Szmelc Conventions'
  echo
  echo '> Global conventions for humans and AI agents: language, git/PR/CI, branch lanes, repo metadata, notifications, verification, subagents, colors, CLI/TUI, Arch/Nix packaging, agent-file formats. Agents load rules lazily: read INDEX.md, then only files whose trigger matches the task.'
  echo
  echo "Entry points: [SKILL.md]($RAW/SKILL.md), [INDEX.md]($RAW/INDEX.md), [index.json]($RAW/index.json). All stable rules in one file: [CONVENTIONS.md]($RAW/CONVENTIONS.md)."
  echo
  echo '## Always on'
  echo "- [$(title global/AGENTS.md)]($RAW/global/AGENTS.md): $ALWAYS_TRIGGER"
  echo
  echo '## Rules'
  for f in "${STABLE[@]}"; do echo "- [$(title "$f")]($RAW/$f): Load when $(trigger "$f")"; done
  echo
  echo '## Skills'
  for f in "${SKILLS[@]}"; do echo "- [$(fm "$f" name)]($RAW/$f): $(fm "$f" description)"; done
  if ((${#EXPERIMENTAL[@]})); then
    echo
    echo '## Experimental'
    for f in "${EXPERIMENTAL[@]}"; do echo "- [$(title "$f")]($RAW/$f): Opt-in only. Load when $(trigger "$f")"; done
  fi
  if ((${#LEGACY[@]})); then
    echo
    echo '## Optional'
    for f in "${LEGACY[@]}"; do echo "- [$(title "$f")]($RAW/$f): Legacy archive"; done
  fi
} | emit llms.txt

# --- CONVENTIONS.md (all stable rules, one file) -----------------------------
demote() { sed -E 's/^(#+) /#\1 /' "$1"; }
{
  echo '# Szmelc Conventions (all-in-one)'
  echo "$GEN_NOTE"
  echo '> One-shot reference for tools that cannot lazy-load (aider `--read`, web chats, project knowledge). Agents with file access use `SKILL.md` + `INDEX.md` instead; never load this file alongside them. Stable rules only; the lazy-load instructions below do not apply here because every stable rule is inlined.'
  for f in global/AGENTS.md "${STABLE[@]}"; do
    echo
    echo '---'
    echo "<!-- source: $f -->"
    demote "$f"
  done
} | emit CONVENTIONS.md

# --- adapters (frontmatter-requiring tools) ----------------------------------
adapter() {
  local dest=$1 front=$2
  {
    printf -- '---\n%s\n---\n' "$front"
    echo "<!-- GENERATED by tools/build.sh from global/AGENTS.md. Do not edit. -->"
    cat global/AGENTS.md
  } | emit "$dest"
}
adapter adapters/cursor/szmelc-conventions.mdc $'description: Szmelc global conventions (always on)\nalwaysApply: true'
adapter adapters/copilot/szmelc-conventions.instructions.md $'applyTo: "**"'
adapter adapters/kiro/szmelc-conventions.md $'inclusion: always'

# --- check mode --------------------------------------------------------------
if ((check)); then
  stale=0
  for f in "${GENERATED[@]}"; do
    if ! cmp -s "$out/$f" "$f"; then echo "stale: $f" >&2; stale=1; fi
  done
  ((stale == 0)) || { echo 'Run tools/build.sh' >&2; exit 1; }
  echo 'generated files up to date'
else
  echo "built: ${GENERATED[*]}"
fi
